-- Target columns of rule and BEGIN ATOMIC INSERT/UPDATE statements in pg_depend.
CREATE TABLE a (x int, y int);
CREATE TABLE t (d int, e int, f int, g int);
CREATE RULE r1 AS ON INSERT TO a DO ALSO INSERT INTO t (e) VALUES (new.x);
CREATE RULE r2 AS ON UPDATE TO a DO ALSO UPDATE t SET f = new.y WHERE g = 1;
CREATE RULE r3 AS ON DELETE TO a DO ALSO DELETE FROM t WHERE d = old.x;
-- Each column change below has one kind of dependent: which of several
-- PostgreSQL names first follows pg_depend's physical row order.
ALTER TABLE t ALTER COLUMN e TYPE bigint;
ALTER TABLE t ALTER COLUMN f TYPE bigint;
CREATE FUNCTION fa() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t (e, f) VALUES (1, 2); UPDATE t SET g = 3 WHERE d = 1; END;
CREATE FUNCTION fb() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t VALUES (1); END;
CREATE FUNCTION fc() RETURNS void LANGUAGE sql BEGIN ATOMIC DELETE FROM t; END;
CREATE FUNCTION fd() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t SELECT 1, 2; END;
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced, deptype FROM pg_depend WHERE refobjid = 't'::regclass ORDER BY 1, 2;
DROP RULE r1 ON a;
DROP RULE r2 ON a;
ALTER TABLE t ALTER COLUMN e TYPE bigint;
ALTER TABLE t ALTER COLUMN f TYPE bigint;
DROP FUNCTION fa();
ALTER TABLE t ALTER COLUMN e TYPE bigint;
ALTER TABLE t ALTER COLUMN f TYPE bigint;
REVOKE ALL ON t FROM PUBLIC;
CREATE ROLE wr;
GRANT INSERT (e) ON t TO wr;
GRANT INSERT ON a TO wr;
CREATE TABLE a2 (x int);
CREATE RULE r4 AS ON INSERT TO a2 DO INSTEAD INSERT INTO t (e) VALUES (new.x);
GRANT INSERT ON a2 TO wr;
SET ROLE wr;
INSERT INTO a2 VALUES (5);
RESET ROLE;
SELECT * FROM t;
DROP TABLE a, a2, t CASCADE;
DROP ROLE wr;
CREATE TABLE t (d int primary key, e int, f int, g int, h int);
CREATE FUNCTION f1() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t (d, e) VALUES (1, 2) ON CONFLICT (d) DO UPDATE SET f = 3; END;
CREATE FUNCTION f2() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t DEFAULT VALUES; END;
CREATE FUNCTION f3() RETURNS int LANGUAGE sql BEGIN ATOMIC INSERT INTO t SELECT * FROM t RETURNING h; END;
CREATE FUNCTION f4() RETURNS void LANGUAGE sql BEGIN ATOMIC UPDATE t SET (e, f) = (1, 2); END;
CREATE FUNCTION f5() RETURNS void LANGUAGE sql BEGIN ATOMIC INSERT INTO t SELECT 1, 2 UNION SELECT d, e FROM t; END;
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced FROM pg_depend WHERE refobjid = 't'::regclass AND classid = 'pg_proc'::regclass ORDER BY 1, 2;
ALTER TABLE t DROP COLUMN g;
DROP TABLE t CASCADE;
